    OR EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE status IN ('planned','running','halted','unknown'))
    OR EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-e4fe81ae8ed7439cd374215dd658') THEN RAISE EXCEPTION 'ce200_exclusive_or_replay'; END IF;
