      AND bytes_reserved+1048576<=bytes_limit AND read_rows_reserved+100<=read_rows_limit AND write_rows_reserved+3<=2000;
  IF NOT FOUND THEN RAISE EXCEPTION 'ce200_budget'; END IF;
