BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $payload$
DECLARE payload jsonb; data jsonb; started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-e4fe81ae8ed7439cd374215dd658' AND status='running' AND operation_hash='e4fe81ae8ed7439cd374215dd6582d9e124c95320e67080ec3e13ec1cd6e5b74' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO data FROM (SELECT id,display_name,packaging,category_id,category_name,unit_price,price_per_unit,price_per_unit_unit,published,synced_at,ean,ingredients,nutrition,source_wh,regions,raw,md5(to_jsonb(p)::text) AS source_row_md5 FROM public.mercadona_products p WHERE (published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)|b[ií]fidus'))
      AND NOT (published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)'))
      AND id COLLATE "C" > '' COLLATE "C" ORDER BY id COLLATE "C" LIMIT 100) q;
  payload:=jsonb_build_object('job_key','ce1-ce200-e4fe81ae8ed7439cd374215dd658','operation_hash','e4fe81ae8ed7439cd374215dd6582d9e124c95320e67080ec3e13ec1cd6e5b74',
    'project_ref','gkffvigcnsesbaihycay','captured_at',started,'kind','supplement','store','mercadona',
    'cursor','','rows',data,'row_count',jsonb_array_length(data),'elapsed_ms',extract(epoch FROM clock_timestamp()-started)*1000);
  IF jsonb_array_length(data)>100 OR octet_length(payload::text)>1040384 THEN RAISE EXCEPTION 'ce200_result_limit'; END IF;
  UPDATE comparator_strict.execution_jobs SET status='succeeded',finished_at=clock_timestamp(),
    receipt=jsonb_build_object('payload_sha256',encode(sha256(convert_to(payload::text,'UTF8')),'hex'),'row_count',jsonb_array_length(data),'payload_bytes',octet_length(payload::text),'elapsed_ms',payload->'elapsed_ms') WHERE job_key='ce1-ce200-e4fe81ae8ed7439cd374215dd658';
  PERFORM set_config('comparator_strict.ce200_response',payload::text,true);
